#!/usr/bin/env bash
# Survey the Linux-specific surface of the AOSP code Gesher will port.
#
#   tools/aosp-survey.sh <aosp-tag> <workdir> <report.md>
#
# Shallow-clones the pinned projects and counts uses of kernel/libc features
# that have no direct Windows equivalent. The report tells us where the
# porting work is, and is regenerated by CI whenever the pin changes.
set -euo pipefail

tag=${1:?aosp tag}
work=${2:?workdir}
report=${3:?report path}

projects=(art libcore bionic system/libbase libnativehelper system/core)

# feature name | extended regex
features=(
  "mmap/munmap|\\bm(un)?map(64)?\\s*\\("
  "mremap|\\bmremap\\s*\\("
  "madvise|\\bmadvise\\s*\\("
  "mprotect|\\bmprotect\\s*\\("
  "memfd_create|\\bmemfd_create\\b"
  "futex|\\bfutex\\b|FUTEX_"
  "signals (sigaction etc.)|\\bsig(action|altstack|procmask|emptyset|addset)\\b|\\bSIGSEGV\\b"
  "ucontext|\\bucontext(_t)?\\b|\\bmcontext"
  "prctl|\\bprctl\\s*\\("
  "/proc filesystem|\"/proc/"
  "epoll / eventfd|\\bepoll_|\\beventfd\\b"
  "fork / exec|\\bfork\\s*\\(|\\bexecv[pe]?\\s*\\("
  "ptrace|\\bptrace\\b"
  "dlopen / dlsym|\\bdl(open|sym|close|error)\\s*\\("
  "pthread|\\bpthread_[a-z_]+\\s*\\("
  "ioctl|\\bioctl\\s*\\("
  "syscall()|\\bsyscall\\s*\\(|__NR_"
  "ashmem|\\bashmem"
  "sched affinity/priority|\\bsched_(setaffinity|getaffinity|setscheduler)\\b|\\bsetpriority\\s*\\("
)

mkdir -p "$work"
for p in "${projects[@]}"; do
  dest="$work/$p"
  if [[ ! -d $dest/.git ]]; then
    git clone --quiet --depth 1 --branch "$tag" \
      "https://android.googlesource.com/platform/$p" "$dest"
  fi
done

count() {  # count <regex> <dir>
  grep -rEo --include='*.cc' --include='*.cpp' --include='*.c' \
    --include='*.h' --include='*.S' -e "$1" "$2" 2>/dev/null | wc -l
}

{
  echo "# AOSP porting surface — \`$tag\`"
  echo
  echo "Matches of Linux-specific APIs in C/C++/asm sources (tests included)."
  echo
  printf "| Feature |"; for p in "${projects[@]}"; do printf " %s |" "$p"; done; echo
  printf "|---|"; for _ in "${projects[@]}"; do printf -- "---:|"; done; echo
  for f in "${features[@]}"; do
    name=${f%%|*}; re=${f#*|}
    printf "| %s |" "$name"
    for p in "${projects[@]}"; do printf " %s |" "$(count "$re" "$work/$p")"; done
    echo
  done
  echo
  echo "## Size"
  echo
  echo "| Project | C/C++ files | Lines |"
  echo "|---|---:|---:|"
  for p in "${projects[@]}"; do
    files=$(find "$work/$p" -type f \( -name '*.cc' -o -name '*.cpp' -o -name '*.c' -o -name '*.h' \) | wc -l)
    lines=$(find "$work/$p" -type f \( -name '*.cc' -o -name '*.cpp' -o -name '*.c' -o -name '*.h' \) -print0 | xargs -0 cat | wc -l)
    echo "| $p | $files | $lines |"
  done
  echo
  echo "## ART runtime hot spots (excluding tests)"
  echo
  echo "Files under \`art/runtime\` with the most Linux-specific matches:"
  echo
  all=$(printf "%s\n" "${features[@]}" | sed 's/^[^|]*|//' | paste -sd'|')
  (cd "$work" && grep -rEc --include='*.cc' --include='*.h' -e "$all" art/runtime 2>/dev/null) \
    | grep -v '_test\.cc:' | grep -v ':0$' | sort -t: -k2 -nr | head -25 \
    | sed 's|^|- `|; s|:|`: |; s|$| lines|'
} > "$report"

echo "report written to $report"
